function validarEvento(e) {
 const tipos=['aguardando_aprovacao','aprovacao_registrada'];
 if(!tipos.includes(e.evento?.tipo)) return null;
 const uuid=v=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
 if(e.meta?.origem_verificada!==true||e.meta?.validacao?.valido!==true||e.meta?.versao_evento!==1||!Number.isSafeInteger(e.meta?.tenant_id)||e.meta.tenant_id<=0||!uuid(e.meta.id_evento)||!uuid(e.meta.execution_id))throw new Error('SLA exige evento autenticado e normalizado pelo Core.');
 if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(e.repositorio?.full_name||'')||!Number.isSafeInteger(e.pr?.numero)||e.pr.numero<=0||!Number.isFinite(Date.parse(e.meta.ocorrido_em)))throw new Error('Identidade ou horário do evento inválido.');
 const inicio=e.evento.tipo==='aguardando_aprovacao';
 if(inicio&&e.risco?.nivel!=='ALTO')throw new Error('A espera deve ser de risco ALTO informado pelo núcleo.');
 if(!inicio&&!['aprovada','alteracoes_solicitadas'].includes(e.aprovacao?.decisao))throw new Error('Decisão de encerramento inválida.');
 const contexto={installation_id:e.meta.tenant_id,task_run_id:e.meta.execution_id,repositorio:e.repositorio.full_name,numero_pr:e.pr.numero,url_pr:'https://github.com/'+e.repositorio.full_name+'/pull/'+e.pr.numero,decisao:inicio?null:e.aprovacao.decisao};
 return {chave:JSON.stringify([contexto.installation_id,contexto.task_run_id,contexto.repositorio.toLowerCase(),contexto.numero_pr]),evento_id:e.meta.id_evento,tipo:inicio?'inicio':'encerrado',ocorrido_em:new Date(e.meta.ocorrido_em).toISOString(),contexto:JSON.stringify(contexto)};
