function politicaPara(contexto, env) {
 let politicas;
 try{politicas=JSON.parse(env.APROVA_SLA_POLITICAS_JSON||'[]');}catch{ return {valida:false,motivo:'APROVA_SLA_POLITICAS_JSON inválido.'}; }
 if(!Array.isArray(politicas))return {valida:false,motivo:'Políticas devem ser uma lista.'};
 const encontrados=politicas.filter(p=>p&&p.installation_id===contexto.installation_id&&typeof p.repositorio==='string'&&p.repositorio.toLowerCase()===contexto.repositorio.toLowerCase());
 if(encontrados.length!==1)return {valida:false,motivo:encontrados.length?'Política ambígua.':'Política do repositório não cadastrada.'};
 const p=encontrados[0],canal=p.canal_slack||env.APROVA_SLA_CANAL_ID||'';
 if(env.APROVA_SLA_HABILITADO!=='true'||p.habilitado!==true)return {valida:false,motivo:'Envios do SLA desabilitados por configuração.'};
 if(!Number.isSafeInteger(p.primeiro_limite_minutos)||p.primeiro_limite_minutos<=0||!Number.isSafeInteger(p.segundo_limite_minutos)||p.segundo_limite_minutos<=p.primeiro_limite_minutos)return {valida:false,motivo:'Definir dois limites positivos, com o segundo maior que o primeiro.'};
 if(!/^[CG][A-Z0-9]{8,}$/.test(canal))return {valida:false,motivo:'Canal Slack do SLA não configurado.'};
 if(p.responsavel_slack&&!/^[UW][A-Z0-9]{8,}$/.test(p.responsavel_slack))return {valida:false,motivo:'ID Slack do responsável inválido; não inferir identidade.'};
 return {valida:true,primeiro:p.primeiro_limite_minutos,segundo:p.segundo_limite_minutos,canal,responsavel:p.responsavel_slack||null};
}

function lerRegistros(rows) {
 const vistos=new Map();
 for(const r of rows){
  if(!r.chave&&!r.tipo&&!r.evento_id)continue;
  let c;try{c=JSON.parse(r.contexto);}catch{throw new Error('Registro SLA inválido; notificações interrompidas para preservar encerramentos.');}
  const chave=JSON.stringify([c.installation_id,c.task_run_id,String(c.repositorio).toLowerCase(),c.numero_pr]);
  if(chave!==r.chave||!Number.isFinite(Date.parse(r.ocorrido_em))||!['inicio','encerrado','reservado_1','reservado_2','enviado_1','enviado_2','incerto_1','incerto_2','cancelado_1','cancelado_2'].includes(r.tipo))throw new Error('Contrato do histórico SLA inválido.');
  const chaveEvento=r.chave+':'+r.tipo+':'+r.evento_id,anterior=vistos.get(chaveEvento);
  if(!anterior||Date.parse(r.ocorrido_em)<Date.parse(anterior.ocorrido_em))vistos.set(chaveEvento,{...r,c});
 }
 return [...vistos.values()];
}

function planejar(rows,env,agora) {
 const registros=lerRegistros(rows),grupos=new Map(),ultimas=new Map();
 for(const r of registros){if(!grupos.has(r.chave))grupos.set(r.chave,[]);grupos.get(r.chave).push(r);if(r.tipo==='inicio'){const pr=JSON.stringify([r.c.installation_id,r.c.repositorio.toLowerCase(),r.c.numero_pr]);const a=ultimas.get(pr);if(!a||Date.parse(r.ocorrido_em)>a.tempo)ultimas.set(pr,{chave:r.chave,tempo:Date.parse(r.ocorrido_em)});}}
 const acoes=[],pendencias=[];let encerrados=0;
 for(const [chave,rs] of grupos){
  if(rs.some(r=>r.tipo==='encerrado')){encerrados++;continue;}
  const inicios=rs.filter(r=>r.tipo==='inicio').sort((a,b)=>Date.parse(a.ocorrido_em)-Date.parse(b.ocorrido_em));if(!inicios.length)continue;
  const inicio=inicios[0],c=inicio.c,pr=JSON.stringify([c.installation_id,c.repositorio.toLowerCase(),c.numero_pr]);if(ultimas.get(pr)?.chave!==chave)continue;
  const p=politicaPara(c,env);if(!p.valida){pendencias.push({chave,motivo:p.motivo});continue;}
  const tempo=Date.parse(inicio.ocorrido_em);if(tempo>agora+300000){pendencias.push({chave,motivo:'Horário de início está no futuro.'});continue;}
  const tipos=new Set(rs.map(r=>r.tipo));let etapa=null;
  if(agora>=tempo+p.primeiro*60000&&!tipos.has('reservado_1')&&!tipos.has('enviado_1')&&!tipos.has('incerto_1')&&!tipos.has('cancelado_1'))etapa=1;
  else if(agora>=tempo+p.segundo*60000&&tipos.has('enviado_1')&&!tipos.has('reservado_2')&&!tipos.has('enviado_2')&&!tipos.has('incerto_2')&&!tipos.has('cancelado_2'))etapa=2;
  if(etapa===2&&!p.responsavel){pendencias.push({chave,motivo:'Segundo limite atingido; cadastrar responsável Slack do repositório.'});continue;}
  if(etapa)acoes.push({chave,etapa,contexto:c,inicio:inicio.ocorrido_em,politica:p,prazo:new Date(tempo+(etapa===1?p.primeiro:p.segundo)*60000).toISOString()});
 }
 return {acoes:acoes.slice(0,10),pendencias:pendencias.slice(0,50),pendencias_total:pendencias.length,encerrados,registros:registros.length,acoes_restantes:Math.max(0,acoes.length-10)};
}

function revalidar(candidato,rows,env,agora,lease) {
 const registros=lerRegistros(rows).filter(r=>r.chave===candidato.chave);
 if(registros.some(r=>r.tipo==='encerrado'))return {...candidato,enviar:false,status:'encerrado_antes_do_aviso'};
 const p=politicaPara(candidato.contexto,env);if(!p.valida)return {...candidato,enviar:false,status:'configuracao_pendente',motivo:p.motivo};
 if(agora>lease-60000)return {...candidato,enviar:false,status:'controle_expirando'};
 if(!registros.some(r=>r.tipo==='inicio'))return {...candidato,enviar:false,status:'inicio_nao_encontrado'};
 if(registros.some(r=>r.tipo==='reservado_'+candidato.etapa||r.tipo==='enviado_'+candidato.etapa||r.tipo==='incerto_'+candidato.etapa||r.tipo==='cancelado_'+candidato.etapa))return {...candidato,enviar:false,status:'aviso_ja_processado'};
 const limite=candidato.etapa===1?p.primeiro:p.segundo;
 if(agora<Date.parse(candidato.inicio)+limite*60000)return {...candidato,enviar:false,status:'prazo_ainda_nao_atingido'};
 if(candidato.etapa===2&&(!p.responsavel||!registros.some(r=>r.tipo==='enviado_1')))return {...candidato,enviar:false,status:'escalonamento_pendente'};
 const c=candidato.contexto;
