 return {...candidato,politica:p,enviar:true,status:'pronto_para_avisar',texto,revalidacao_nucleo:{status:'indisponivel',motivo:'Endpoint de consulta do estado atual ainda não existe; acompanhamento baseado em eventos.'}};
}

function confirmarEnvio(candidato,resposta) {
 const ts=resposta.ts||resposta.message_timestamp;
 const confirmado=resposta.ok!==false&&resposta.channel===candidato.politica.canal&&typeof ts==='string'&&/^\d+\.\d+$/.test(ts);
 return {chave:candidato.chave,evento_id:'sla:'+candidato.chave+':'+candidato.etapa+':resultado',tipo:(confirmado?'enviado_':'incerto_')+candidato.etapa,ocorrido_em:new Date().toISOString(),contexto:JSON.stringify({...candidato.contexto,slack:confirmado?{canal:resposta.channel,ts}:null,resultado:confirmado?'confirmado':'envio_nao_confirmado_sem_retry_automatico'})};
}

